local list, objectives, rewards, text, places

local function Split(raw, fn)
    if not raw then return end
    for line in raw:gmatch("[^\n]+") do
        local fields = {}
        for field in (line .. "\t"):gmatch("([^\t]*)\t") do
            fields[#fields + 1] = field
        end
        fn(fields)
    end
end

-- The list, and nothing else. Opening the tab costs this.
function Quests.Load()
    if list then return list end
    list = {}
    Split(rawList, function(f)
        local id = tonumber(f[1])
        if id then
            list[id] = {
                id    = id,
                level = tonumber(f[2]) or 0,
                tag   = (f[3] ~= "" and f[3]) or nil,
                xp    = tonumber(f[4]) or 0,
                money = tonumber(f[5]) or 0,
                -- Where this quest's words and numbers came from when
                -- the server did not supply them: "t" the story, "n"
                -- the numbers, "" all first-hand. See Quests.FromGame.
                origin = (f[6] ~= "" and f[6]) or nil,
                title = f[7] or "?",
            }
        end
    end)
    rawList = nil
    return list
end

function Quests.Get(id)
    return Quests.Load()[tonumber(id) or 0]
end

-- Whether a part of this quest came from the game itself rather than
-- from a public database. `what` is "text" or "numbers".
function Quests.FromGame(id, what)
    local row = Quests.Get(id)
    if not row or not row.origin then return true end
    return not row.origin:find((what == "text") and "t" or "n", 1, true)
end

function Quests.All()
    return Quests.Load()
end

-- Asked for when a quest is opened, not before.
function Quests.Objectives(id)
    if not objectives then
        objectives = {}
        Split(rawObjectives, function(f)
            local questID = tonumber(f[1])
            if questID then
                local lines = {}
                for index = 2, #f do
                    if f[index] ~= "" then lines[#lines + 1] = f[index] end
                end
                if #lines > 0 then objectives[questID] = lines end
            end
        end)
        rawObjectives = nil
    end
    return objectives[tonumber(id) or 0]
end

function Quests.Rewards(id)
    if not rewards then
        rewards = {}
        Split(rawRewards, function(f)
            local questID = tonumber(f[1])
            if questID then
                local into = rewards[questID] or {}
                into[#into + 1] = {
                    kind  = f[2],
                    item  = tonumber(f[3]),
                    count = tonumber(f[4]) or 1,
                    name  = f[5] or "?",
                }
                rewards[questID] = into
            end
        end)
        rawRewards = nil
    end
    return rewards[tonumber(id) or 0]
end

-- The objective summary and the story, with the newlines put back.
-- Where a quest lives, as far as anybody else knows.
--
-- CONJECTURE, and the only part of this file that is. Everything else
-- came from the game or from a database filling a blank in what the game
-- said; this came from a crawl of 60.tools and describes something the
-- client will not tell us at all. A quest's zone and the name of whoever
-- offers it do not reach you until you are standing in front of them, so
-- for a quest nobody has met there is no first-hand answer to prefer.
--
-- Read it as "somebody says he stands in Duskwood", never as a position.
-- There are no coordinates here on purpose - a name and a zone are enough
-- to walk towards and not enough to pretend to precision. Anything a
-- player actually witnesses replaces this outright; see
-- Modules/Codex/Sources/QuestCatalog.lua.
function Quests.Place(id)
    if not places then
        places = {}
        Split(rawPlaces, function(f)
            local questID = tonumber(f[1])
            if questID then
                places[questID] = {
                    zone     = (f[2] ~= "" and f[2]) or nil,
                    faction  = (f[3] ~= "" and f[3]) or nil,
                    minLevel = tonumber(f[4]),
                    giver    = (f[5] ~= "" and f[5]) or nil,
                    turnIn   = (f[6] ~= "" and f[6]) or nil,
                }
            end
        end)
        rawPlaces = nil
    end
    return places[tonumber(id) or 0]
end

function Quests.Text(id)
    if not text then
        text = {}
        Split(rawText, function(f)
            local questID = tonumber(f[1])
            if questID then
                text[questID] = {
                    summary     = (f[2] ~= "" and f[2]:gsub("\\n", "\n")) or nil,
                    description = (f[3] ~= "" and f[3]:gsub("\\n", "\n")) or nil,
                }
            end
        end)
        rawText = nil
    end
    return text[tonumber(id) or 0]
end
